import pty, os, subprocess, time, select, signal, termios, struct, fcntl, re

def run_with_pty_input(args, inputs, timeout=4, cols=80, rows=24):
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", rows, cols, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, preexec_fn=os.setsid, env={**os.environ, "TERM":"xterm-256color"})
    os.close(slave)
    data=b""
    start=time.time()
    input_idx=0
    while time.time()-start < timeout:
        now=time.time()-start
        while input_idx < len(inputs) and now >= inputs[input_idx][0]:
            os.write(master, inputs[input_idx][1])
            input_idx+=1
        r,_,_ = select.select([master], [], [], 0.1)
        if r:
            try:
                chunk=os.read(master, 8192)
                if not chunk:
                    break
                data+=chunk
            except OSError:
                break
        if proc.poll() is not None and input_idx>=len(inputs):
            time.sleep(0.2)
            r,_,_ = select.select([master], [], [], 0.2)
            if r:
                try:
                    data+=os.read(master, 8192)
                except: pass
            break
    try:
        os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
    except: pass
    try:
        proc.wait(timeout=1)
    except: pass
    try: os.close(master)
    except: pass
    return data

def esc_clean(s):
    # remove ansi escape sequences crudely
    return re.sub(r'\x1b\[[^a-zA-Z]*[a-zA-Z]|\x1b\?.*?[\x07]|[\r\n]+', '', s)

# test various combos and observe more
for cols in [80, 120, 40]:
    for test_args in [["-w","5"], ["-w","15"], ["-p","hello world"], ["-f","2"]]:
        d = run_with_pty_input(["./executable"]+test_args, [], timeout=1.5, cols=cols)
        print(f"cols={cols} args={test_args} raw={d[:500]!r} clean={esc_clean(d.decode(errors='ignore'))[:200]!r}")

