        Ok(m) => m,
        Err(e) => {
            // clap will handle colored output based on is_terminal; we just exit with code 2 as clap does
            e.exit();
        }
    };
    // Check tty
    if !atty::is(atty::Stream::Stdin) {
        eprintln!("error: stdin must be a tty\n\nUSAGE:\n    thokr [OPTIONS]\n\nFor more information try --help");
        std::process::exit(2);
