    // Extract opts
    let number_of_words: usize = *matches.get_one::<usize>("number_of_words").unwrap();
    let supported_language = matches.get_one::<String>("supported_language").unwrap().clone();
    let prompt_opt = matches.get_one::<String>("prompt").cloned();
    let full_sentences = matches.get_one::<usize>("full_sentences").cloned();
    let number_of_secs = matches.get_one::<usize>("number_of_secs").cloned();

    // Generate prompt
    let prompt = if let Some(p) = prompt_opt {
        p
    } else if let Some(n) = full_sentences {
        generate_sentences(n)
    } else {
        generate_words(number_of_words, &supported_language)
    };

    // run tui
    if let Err(e) = run_tui(prompt, number_of_words, supported_language, full_sentences, number_of_secs) {
        eprintln!("error: {}", e);
        std::process::exit(1);
    }
}

fn generate_words(n: usize, lang: &str) -> String {
    let words = get_wordlist(lang);
    let mut rng = rand::thread_rng();
    use rand::seq::SliceRandom;
    let mut out = Vec::new();
    for _ in 0..n {
        if let Some(w) = words.choose(&mut rng) {
            out.push(w.clone());
        }
    }
    out.join(" ")
}

fn generate_sentences(n: usize) -> String {
    if n==0 { return String::new(); }
    let words = get_wordlist("english");
    let mut rng = rand::thread_rng();
    use rand::seq::SliceRandom;
    let mut sentences = Vec::new();
    for _ in 0..n {
        let len = rand::random::<usize>() % 8 + 5; // 5-12
        let mut ws = Vec::new();
        for i in 0..len {
            if let Some(w) = words.choose(&mut rng) {
                let mut w = w.clone();
                if i==0 { w = capitalize(&w); }
                ws.push(w);
            }
        }
        sentences.push(ws.join(" ") + ".");
    }
    sentences.join(" ")
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
    }
}

fn get_wordlist(lang: &str) -> Vec<String> {
    match lang {
        "english" => ENGLISH_WORDS.iter().map(|s| s.to_string()).collect(),
        "english1k" => ENGLISH1K_WORDS.iter().map(|s| s.to_string()).collect(),
        "english10k" => ENGLISH10K_WORDS.iter().map(|s| s.to_string()).collect(),
        _ => ENGLISH_WORDS.iter().map(|s| s.to_string()).collect(),
    }
}

