use std::io::{self, Write};
use std::time::{Instant, Duration};
use clap::{Command, Arg, value_parser};

fn main() {
    let mut cmd = Command::new("thokr")
        .version("0.4.1")
        .about("sleek typing tui with visualized results and historical logging")
        .arg(Arg::new("number_of_words").short('w').long("number-of-words").value_name("NUMBER_OF_WORDS").default_value("15").value_parser(value_parser!(usize)))
        .arg(Arg::new("supported_language").short('l').long("supported-language").value_name("SUPPORTED_LANGUAGE").default_value("english").value_parser(["english","english1k","english10k"]))
        .arg(Arg::new("prompt").short('p').long("prompt").value_name("PROMPT"))
        .arg(Arg::new("full_sentences").short('f').long("full-sentences").value_name("NUMBER_OF_SENTENCES").value_parser(value_parser!(usize)))
        .arg(Arg::new("number_of_secs").short('s').long("number-of-secs").value_name("NUMBER_OF_SECS").value_parser(value_parser!(usize)));
    // need to handle help/version order: clap does automatically, but our earlier tests showed that -h -V should show help, -V -h should show version. Clap's default is to give version if both present? Let's check.
    // We will let clap handle.
    let matches = match cmd.try_get_matches_from(std::env::args()) {
        Ok(m) => m,
        Err(e) => {
            // clap will handle colored output based on is_terminal; we just exit with code 2 as clap does
            e.exit();
        }
    };
    // Check tty
    if !atty::is(atty::Stream::Stdin) {
        eprintln!("error: stdin must be a tty\n\nUSAGE:\n    thokr [OPTIONS]\n\nFor more information try --help");
        std::process::exit(2);
    }
    // Extract opts
    let number_of_words: usize = *matches.get_one::<usize>("number_of_words").unwrap();
    let supported_language = matches.get_one::<String>("supported_language").unwrap().clone();
    let prompt_opt = matches.get_one::<String>("prompt").cloned();
    let full_sentences = matches.get_one::<usize>("full_sentences").cloned();
    let number_of_secs = matches.get_one::<usize>("number_of_secs").cloned();

    // Generate prompt
    let prompt = if let Some(p) = prompt_opt {
        p
    } else if let Some(n) = full_sentences {
        generate_sentences(n)
    } else {
        generate_words(number_of_words, &supported_language)
    };

    // run tui
    if let Err(e) = run_tui(prompt, number_of_words, supported_language, full_sentences, number_of_secs) {
        eprintln!("error: {}", e);
        std::process::exit(1);
    }
}

fn generate_words(n: usize, lang: &str) -> String {
    let words = get_wordlist(lang);
    let mut rng = rand::thread_rng();
    use rand::seq::SliceRandom;
    let mut out = Vec::new();
    for _ in 0..n {
        if let Some(w) = words.choose(&mut rng) {
            out.push(w.clone());
        }
    }
    out.join(" ")
}

fn generate_sentences(n: usize) -> String {
    if n==0 { return String::new(); }
    let words = get_wordlist("english");
    let mut rng = rand::thread_rng();
    use rand::seq::SliceRandom;
    let mut sentences = Vec::new();
    for _ in 0..n {
        let len = rand::random::<usize>() % 8 + 5; // 5-12
        let mut ws = Vec::new();
        for i in 0..len {
            if let Some(w) = words.choose(&mut rng) {
                let mut w = w.clone();
                if i==0 { w = capitalize(&w); }
                ws.push(w);
            }
        }
        sentences.push(ws.join(" ") + ".");
    }
    sentences.join(" ")
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
    }
}

fn get_wordlist(lang: &str) -> Vec<String> {
    match lang {
        "english" => ENGLISH_WORDS.iter().map(|s| s.to_string()).collect(),
        "english1k" => ENGLISH1K_WORDS.iter().map(|s| s.to_string()).collect(),
        "english10k" => ENGLISH10K_WORDS.iter().map(|s| s.to_string()).collect(),
        _ => ENGLISH_WORDS.iter().map(|s| s.to_string()).collect(),
    }
}

