    print!("{}", txt);
}
fn generate_words(n: usize, lang: &str) -> String {
    let words = get_wordlist(lang);
    let mut out = Vec::new();
    for _ in 0..n {
        let idx = (rand::random::<usize>() % words.len());
        out.push(words[idx].to_string());
    }
    out.join(" ")
}
fn generate_sentences(n: usize) -> String {
    if n==0 { return String::new(); }
    let words = get_wordlist("english");
    let mut sentences = Vec::new();
    for _ in 0..n {
        let len = rand::random::<usize>() % 8 + 5;
        let mut ws = Vec::new();
        for i in 0..len {
            let w = words[rand::random::<usize>() % words.len()].to_string();
            let w = if i==0 { capitalize(&w) } else { w };
            ws.push(w);
        }
        sentences.push(ws.join(" ") + ".");
    }
    sentences.join(" ")
}
fn capitalize(s: &str) -> String {
    let mut c=s.chars();
    match c.next() { None=> String::new(), Some(f)=> f.to_uppercase().collect::<String>() + c.as_str()}
}
