def generate_prompt(opts):
    if opts["prompt"] is not None:
        return opts["prompt"]
    if opts["full_sentences"] is not None:
        n=opts["full_sentences"]
        if n==0: return ""
        sentences=[]
        for _ in range(n):
            l=random.randint(5,10)
            ws=[random.choice(ENGLISH_WORDS) for _ in range(l)]
            ws[0]=ws[0].capitalize()
            sentences.append(" ".join(ws)+".")
        return " ".join(sentences)
    else:
        n=opts["number_of_words"]
        lang=opts["supported_language"]
        lst=ENGLISH_WORDS if lang=="english" else ENGLISH1K_WORDS if lang=="english1k" else ENGLISH10K_WORDS
        return " ".join(random.choice(lst) for _ in range(n))

