    path=get_log_path()
    header="date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n"
    if opts["full_sentences"] is not None:
        if opts["prompt"] is not None:
            num_words=0
        else:
            num_words=len(prompt.split()) if prompt.strip() else 0
    else:
        num_words=opts["number_of_words"]
    num_secs=f"{opts['number_of_secs']:.2f}" if opts["number_of_secs"] is not None else ""
    elapsed_s=f"{elapsed:.2f}"
    wpm_s="inf" if math.isinf(wpm) else str(int(round(wpm)))
    acc_s=str(int(round(acc)))
    sd_s=f"{sd:.2f}"
    now=t.localtime()
    date_str=f"{t.strftime('%a',now)} {t.strftime('%b',now)} {now.tm_mday:2d} {t.strftime('%H:%M:%S',now)} {now.tm_year}"
    row=f"{date_str},{num_words},{num_secs},{elapsed_s},{wpm_s},{acc_s},{sd_s}\n"
    need=not path.exists() or path.stat().st_size==0
    with open(path,"a") as f:
        if need: f.write(header)
        f.write(row)

