import pty, os, subprocess, time, select, struct, fcntl, termios, signal, re, tempfile, pathlib

def raw(prog, args, inputs, cols=80):
    master, slave=pty.openpty()
    winsize=struct.pack("HHHH",24,cols,0,0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    env={**os.environ,"TERM":"xterm-256color"}
    proc=subprocess.Popen([prog]+args, stdin=slave, stdout=slave, stderr=slave, preexec_fn=os.setsid, env=env)
    os.close(slave)
    data=b""
    time.sleep(0.5)
    r,_,_=select.select([master],[],[],0.2)
    if r:
        data+=os.read(master,4096)
    for delay, b in inputs:
        time.sleep(delay)
        os.write(master, b)
        time.sleep(0.2)
        r,_,_=select.select([master],[],[],0.3)
        if r:
            try: data+=os.read(master,4096)
            except: pass
    time.sleep(0.5)
    r,_,_=select.select([master],[],[],0.4)
    if r:
        try: data+=os.read(master,4096)
        except: pass
    try: os.killpg(os.getpgid(proc.pid),signal.SIGTERM)
    except: pass
    try: proc.wait(timeout=1)
    except: pass
    try: os.close(master)
    except: pass
    return data

